primitives { Panel } from "../../support/layout.capabilities.js";
primitives { Button, Heading } from "../../support/content.capabilities.js";
properties { ButtonLabel, HeadingText } from "../../support/content.capabilities.js";
properties { PanelGap } from "../../support/layout.capabilities.js";

